1	package remote
2	
3	import (
4		"context"
5		"fmt"
6		"log/slog"
7		"os"
8		"sort"
9		"strings"
10	
11		"github.com/entireio/cli/cmd/entire/cli/gitremote"
12		"github.com/entireio/cli/cmd/entire/cli/gitrepo"
13		"github.com/entireio/cli/cmd/entire/cli/logging"
14		"github.com/entireio/cli/cmd/entire/cli/settings"
15	
16		"github.com/go-git/go-git/v6"
17	)
18	
19	const originRemote = "origin"
20	
21	const (
22		ProtocolSSH    = gitremote.ProtocolSSH
23		ProtocolHTTPS  = gitremote.ProtocolHTTPS
24		ProtocolEntire = gitremote.ProtocolEntire
25	)
26	
27	// Info is an alias for gitremote.Info.
28	type Info = gitremote.Info
29	
30	// FetchURLOptions configures FetchURL.
31	type FetchURLOptions struct {
32		WorktreeRoot string
33	}
34	
35	// FetchURL returns the effective checkpoint fetch URL for the current repository.
36	// If strategy_options.checkpoint_remote is configured, the returned URL is derived
37	// from the origin remote's protocol/host and the configured checkpoint repo.
38	// Otherwise, the origin remote URL is returned directly.
39	//
40	// If ENTIRE_CHECKPOINT_TOKEN is set and a checkpoint remote is configured, HTTPS is
41	// forced so the token can be used even when origin is configured via SSH.
42	func FetchURL(ctx context.Context, opts ...FetchURLOptions) (string, error) {
43		url, _, err := fetchURLAuthoritative(ctx, opts...)
44		return url, err
45	}
46	
47	// fetchURLAuthoritative is FetchURL plus whether the returned URL is
48	// authoritative for checkpoint refs. It is false exactly when a
49	// checkpoint_remote IS configured (or cannot be determined) but resolution
50	// fell back to the origin URL — a remote that by construction does not host
51	// the configured checkpoint refs. Callers that classify "ref absent on the
52	// remote" (FetchCheckpointRef's ls-remote probe) must not treat emptiness on
53	// a non-authoritative target as absence.
54	func fetchURLAuthoritative(ctx context.Context, opts ...FetchURLOptions) (string, bool, error) {
55		var opt FetchURLOptions
56		if len(opts) > 0 {
57			opt = opts[0]
58		}
59	
60		getRemoteURL := GetRemoteURL
61		if opt.WorktreeRoot != "" {
62			ctx = settings.WithWorktreeRoot(ctx, opt.WorktreeRoot)
63			getRemoteURL = func(ctx context.Context, remoteName string) (string, error) {
64				return GetRemoteURLInDir(ctx, opt.WorktreeRoot, remoteName)
65			}
66		}
67	
68		withToken := strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar)) != ""
69	
70		originURL, originErr := getRemoteURL(ctx, originRemote)
71		if originErr != nil {
72			originURL = ""
73		}
74	
75		if originURL != "" && withToken {
76			if tokenURL, ok := deriveTokenOriginURL(originURL); ok {
77				originURL = tokenURL
78			}
79		}
80	
81		s, err := settings.Load(ctx)
82		if err != nil {
83			if originURL != "" {
84				logFallback(ctx, "fetch", originURL, "load settings", err)
85				// Settings unreadable → checkpoint_remote unknown; conservative:
86				// do not certify origin as authoritative for checkpoint refs.
87				return originURL, false, nil
88			}
89			return "", false, fmt.Errorf("load settings: %w", err)
90		}
91	
92		config := s.GetCheckpointRemote()
93		if config == nil {
94			if originURL == "" {
95				// Genuinely no remote to fetch checkpoints from: no origin remote and
96				// no configured checkpoint_remote. Tagged with the sentinel so callers
97				// classify a probe failure as absence rather than a real error.
98				return "", false, fmt.Errorf("no checkpoint remote configured (no fetch URL: %w): %w", originErr, errNoCheckpointRemoteConfigured)
99			}
100			// No checkpoint_remote configured: origin IS the checkpoint host.
101			return originURL, true, nil
102		}
103	
104		if withToken {
105			host, ok := providerHost(config.Provider)
106			if ok {
107				checkpointURL, err := deriveCheckpointURLFromInfo(&Info{
108					Protocol: ProtocolHTTPS,
109					Host:     host,
110				}, config)
111				if err == nil {
112					return checkpointURL, true, nil
113				}
114			}
115	
116			// In token-based execution path, short-circuit to avoid additional
117			// change in protocol.
118			if originURL != "" {
119				return originURL, false, nil
120			}
121		}
122	
123		if originURL == "" {
124			return "", false, fmt.Errorf("no fetch URL found: %w", originErr)
125		}
126	
127		info, err := ParseURL(originURL)
128		if err != nil {
129			logFallback(ctx, "fetch", originURL, "parse origin remote URL", err)
130			return originURL, false, nil
131		}
132	
133		checkpointURL, err := deriveCheckpointURLFromInfo(info, config)
134		if err != nil {
135			// Origin's protocol can't be mapped to a checkpoint URL (e.g. file://,
136			// or an entire:// mirror of a different forge than the configured
137			// provider). Honor the configured checkpoint_remote by targeting the
138			// provider's canonical host over HTTPS rather than falling back to origin.
139			if providerURL, ok := resolveProviderCheckpointURL(ctx, config, opt.WorktreeRoot); ok {
140				return providerURL, true, nil
141			}
142			logFallback(ctx, "fetch", originURL, "derive checkpoint remote URL", err)
143			return originURL, false, nil
144		}
145	
146		return checkpointURL, true, nil
147	}
148	
149	// PushURL returns the effective checkpoint push URL for the current repository.
150	// Unlike FetchURL:
151	//   - it derives protocol from the requested push remote, not always origin
152	//   - it skips checkpoint remote use when the push remote owner differs
153	//     from the configured checkpoint remote owner
154	//
155	// If ENTIRE_CHECKPOINT_TOKEN is set, HTTPS is forced so the token can be used
156	// even when the push remote is configured via SSH.
157	//
158	// The boolean return value reports whether a dedicated checkpoint_remote is
159	// configured and should be used for push. When false, the returned URL is the
160	// repository's origin URL as a fallback.
161	func PushURL(ctx context.Context, pushRemoteName string) (string, bool, error) {
162		originURL := ""
163		if resolvedOriginURL, err := GetRemoteURL(ctx, originRemote); err == nil {
164			originURL = resolvedOriginURL
165		}
166	
167		s, err := settings.Load(ctx)
168		if err != nil {
169			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
170			if fallbackErr == nil {
171				logFallback(ctx, "push", fallbackURL, "load settings", err,
172					slog.String("push_remote", pushRemoteName),
173				)
174				return fallbackURL, false, nil
175			}
176			return "", false, fmt.Errorf("load settings: %w", err)
177		}
178	
179		config := s.GetCheckpointRemote()
180		if config == nil {
181			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
182			if fallbackErr != nil {
183				return "", false, fmt.Errorf("no push URL found: %w", fallbackErr)
184			}
185			return fallbackURL, false, nil
186		}
187	
188		pushRemoteURL, err := GetRemoteURL(ctx, pushRemoteName)
189		if err != nil {
190			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
191			if fallbackErr == nil {
192				logFallback(ctx, "push", fallbackURL, "get push remote URL", err,
193					slog.String("push_remote", pushRemoteName),
194				)
195				return fallbackURL, false, nil
196			}
197			return "", true, fmt.Errorf("no push URL found: %w", err)
198		}
199	
200		pushInfo, err := ParseURL(pushRemoteURL)
201		if err != nil {
202			if originURL != "" {
203				logFallback(ctx, "push", originURL, "parse push remote URL", err,
204					slog.String("push_remote", pushRemoteName),
205				)
206				return originURL, false, nil
207			}
208			return "", true, fmt.Errorf("no push URL found: %w", err)
209		}
210		withToken := strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar)) != ""
211		if withToken && isDirectGitTransport(pushInfo.Protocol) {
212			// Coerce a direct (ssh/https) remote to HTTPS so the token applies,
213			// keeping the host so enterprise installations stay on their own host.
214			// An entire:// remote carries a cluster host that isn't a usable HTTPS
215			// host, so it's handled separately after the owner check below.
216			//
217			// Keep the port only when the source was already HTTPS. SSH ports
218			// (e.g., :2222) don't map to HTTPS ports on the same host.
219			port := ""
220			if pushInfo.Protocol == ProtocolHTTPS {
221				port = pushInfo.Port
222			}
223			pushInfo = &Info{
224				Protocol: ProtocolHTTPS,
225				Host:     pushInfo.Host,
226				Port:     port,
227				Owner:    pushInfo.Owner,
228				Repo:     pushInfo.Repo,
229			}
230		}
231	
232		checkpointOwner := config.Owner()
233		if pushInfo.Owner != "" && checkpointOwner != "" && !strings.EqualFold(pushInfo.Owner, checkpointOwner) {
234			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
235			if fallbackErr != nil {
236				return "", false, fmt.Errorf("no push URL found: %w", fallbackErr)
237			}
238			return fallbackURL, false, nil
239		}
240	
241		if withToken && pushInfo.Protocol == ProtocolEntire {
242			// The checkpoint token is an HTTPS credential for the provider host;
243			// it can't ride through the entire:// helper (which does its own
244			// auth). Route to the provider over HTTPS instead of the mirror.
245			if providerURL, ok := resolveProviderCheckpointURL(ctx, config, ""); ok {
246				return providerURL, true, nil
247			}
248		}
249	
250		pushURL, err := deriveCheckpointURLFromInfo(pushInfo, config)
251		if err != nil {
252			// The push remote's protocol can't be mapped to a checkpoint URL
253			// (e.g. file://, or an entire:// mirror of a different forge than the
254			// configured provider). Honor the configured checkpoint_remote by
255			// targeting the provider's canonical host over HTTPS rather than
256			// misrouting checkpoints to the origin remote.
257			if providerURL, ok := resolveProviderCheckpointURL(ctx, config, ""); ok {
258				return providerURL, true, nil
259			}
260			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
261			if fallbackErr == nil {
262				logFallback(ctx, "push", fallbackURL, "derive push checkpoint URL", err,
263					slog.String("push_remote", pushRemoteName),
264				)
265				return fallbackURL, false, nil
266			}
267			return "", true, fmt.Errorf("no push URL found: %w", err)
268		}
269	
270		return pushURL, true, nil
271	}
272	
273	// Configured reports whether a structured checkpoint_remote is configured.
274	func Configured(ctx context.Context) bool {
275		s, err := settings.Load(ctx)
276		if err != nil {
277			logging.Warn(ctx, "checkpoint remote configuration unavailable; treating as not configured",
278				slog.String("error", err.Error()),
279			)
280			return false
281		}
282		return s.GetCheckpointRemote() != nil
283	}
284	
285	// GetRemoteURL returns the URL configured for the named git remote.
286	func GetRemoteURL(ctx context.Context, remoteName string) (string, error) {
287		url, err := gitremote.GetRemoteURL(ctx, remoteName)
288		if err != nil {
289			return "", fmt.Errorf("get remote URL: %w", err)
290		}
291		return url, nil
292	}
293	
294	// GetRemoteURLInDir returns the URL configured for the named git remote in dir.
295	func GetRemoteURLInDir(ctx context.Context, dir, remoteName string) (string, error) {
296		url, err := gitremote.GetRemoteURLInDir(ctx, dir, remoteName)
297		if err != nil {
298			return "", fmt.Errorf("get remote URL: %w", err)
299		}
300		return url, nil
301	}
302	
303	// ParseURL parses a git remote URL (SSH SCP-style or HTTPS) into its components.
304	func ParseURL(rawURL string) (*Info, error) {
305		info, err := gitremote.ParseURL(rawURL)
306		if err != nil {
307			return nil, fmt.Errorf("parse URL: %w", err)
308		}
309		return info, nil
310	}
311	
312	// isDirectGitTransport reports whether the protocol talks to the git host
313	// directly over ssh/https (where the host is a usable HTTPS host for token
314	// auth), as opposed to a remote helper scheme like entire:// or a local
315	// file://.
316	func isDirectGitTransport(protocol string) bool {
317		return protocol == ProtocolSSH || protocol == ProtocolHTTPS
318	}
319	
320	func deriveCheckpointURLFromInfo(info *Info, config *settings.CheckpointRemoteConfig) (string, error) {
321		switch info.Protocol {
322		case ProtocolSSH:
323			// SCP-style (git@host:repo) doesn't support ports. When a non-default
324			// port is set (e.g., from ssh://git@host:2222/...), use the ssh:// URL form.
325			if info.Port != "" {
326				return fmt.Sprintf("ssh://git@%s/%s.git", info.HostPort(), config.Repo), nil
327			}
328			return fmt.Sprintf("git@%s:%s.git", info.Host, config.Repo), nil
329		case ProtocolHTTPS:
330			return fmt.Sprintf("https://%s/%s.git", info.HostPort(), config.Repo), nil
331		case ProtocolEntire:
332			// entire:// push-through mirrors are cluster-scoped: keep the cluster
333			// host and forge segment, swap in the checkpoint repo. Only derivable
334			// when the forge maps back to the configured provider's host, so a
335			// github checkpoint_remote never routes through another forge's mirror.
336			host, ok := providerHost(config.Provider)
337			if !ok || !strings.EqualFold(info.CanonicalHost(), host) {
338				return "", fmt.Errorf("entire:// remote forge %q does not match checkpoint provider %q", info.Forge, config.Provider)
339			}
340			return fmt.Sprintf("entire://%s/%s/%s", info.HostPort(), info.Forge, config.Repo), nil
341		default:
342			return "", fmt.Errorf("unsupported protocol %q in remote URL", info.Protocol)
343		}
344	}
345	
346	// resolveProviderCheckpointURL builds the checkpoint URL for the configured
347	// provider, choosing the transport from what's already configured for that
348	// endpoint. It is the fallback used when the push/origin remote's protocol can't
349	// be mapped to a git transport (e.g. entire://, file://): the configured
350	// checkpoint_remote names a concrete provider, so checkpoints go there rather
351	// than being misrouted to the origin remote.
352	//
353	// Transport precedence:
354	//  1. ENTIRE_CHECKPOINT_TOKEN set -> HTTPS on the provider host (the token is
355	//     the credential).
356	//  2. An existing remote already targets the provider host -> reuse its scheme,
357	//     so checkpoints use the same auth the user already has for that endpoint.
358	//  3. Otherwise SSH on the provider host.
359	//
360	// Returns ok=false when no transport can be determined (unknown provider with no
361	// usable signal), in which case the caller falls back to the origin remote.
362	func resolveProviderCheckpointURL(ctx context.Context, config *settings.CheckpointRemoteConfig, dir string) (string, bool) {
363		repo, err := openRepoAt(ctx, dir)
364		if err != nil {
365			repo = nil // Fall back to env/provider-only signals.
366		}
367	
368		info, ok := pickProviderTransport(repo, config)
369		if !ok {
370			return "", false
371		}
372		url, err := deriveCheckpointURLFromInfo(info, config)
373		if err != nil {
374			return "", false
375		}
376		return url, true
377	}
378	
379	// pickProviderTransport returns the protocol/host/port to use when deriving a
380	// checkpoint URL, following the precedence documented on
381	// resolveProviderCheckpointURL.
382	func pickProviderTransport(repo *git.Repository, config *settings.CheckpointRemoteConfig) (*Info, bool) {
383		host, hostOK := providerHost(config.Provider)
384	
385		// 1. Explicit token -> HTTPS on the provider host.
386		if hostOK && strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar)) != "" {
387			return &Info{Protocol: ProtocolHTTPS, Host: host}, true
388		}
389	
390		// 2. An existing remote already targeting the provider host -> reuse scheme.
391		if hostOK && repo != nil {
392			if info, ok := findRemoteInfoForHost(repo, host); ok {
393				return &Info{Protocol: info.Protocol, Host: info.Host, Port: info.Port}, true
394			}
395		}
396	
397		// 3. Default to SSH on the provider host.
398		if hostOK {
399			return &Info{Protocol: ProtocolSSH, Host: host}, true
400		}
401	
402		return nil, false
403	}
404	
405	// openRepoAt opens the git repository at dir (current directory when dir is
406	// empty). It routes through gitrepo, the single reftable-aware opener, so a
407	// reftable repository is opened via the git-CLI storer rather than rejected by
408	// go-git's extension check. gitrepo.OpenCurrent resolves the worktree root from
409	// the current directory (the walk-up equivalent of the previous DetectDotGit
410	// open) when no explicit root is given.
411	func openRepoAt(ctx context.Context, dir string) (*git.Repository, error) {
412		if dir == "" {
413			repo, err := gitrepo.OpenCurrent(ctx)
414			if err != nil {
415				return nil, fmt.Errorf("open git repository: %w", err)
416			}
417			return repo, nil
418		}
419		repo, err := gitrepo.OpenPath(dir)
420		if err != nil {
421			return nil, fmt.Errorf("open git repository: %w", err)
422		}
423		return repo, nil
424	}
425	
426	// findRemoteInfoForHost returns the parsed Info of the first configured git
427	// remote (in deterministic name order) whose host matches host and whose
428	// protocol is a usable git transport (ssh/https). entire:// and other
429	// non-transport remotes are ignored.
430	func findRemoteInfoForHost(repo *git.Repository, host string) (*Info, bool) {
431		cfg, err := repo.Config()
432		if err != nil {
433			return nil, false
434		}
435		names := make([]string, 0, len(cfg.Remotes))
436		for name := range cfg.Remotes {
437			names = append(names, name)
438		}
439		sort.Strings(names)
440		for _, name := range names {
441			for _, rawURL := range cfg.Remotes[name].URLs {
442				info, err := gitremote.ParseURL(rawURL)
443				if err != nil {
444					continue
445				}
446				if strings.EqualFold(info.Host, host) && isDirectGitTransport(info.Protocol) {
447					return info, true
448				}
449			}
450		}
451		return nil, false
452	}
453	
454	func deriveTokenOriginURL(originURL string) (string, bool) {
455		info, err := gitremote.ParseURL(originURL)
456		if err != nil {
457			return "", false
458		}
459		if info.Host == "" || info.Owner == "" || info.Repo == "" {
460			return "", false
461		}
462		// Keep the port only when the source was already HTTPS. SSH ports
463		// (e.g., :2222) don't map to HTTPS ports on the same host.
464		hostPort := info.Host
465		if info.Protocol == ProtocolHTTPS {
466			hostPort = info.HostPort()
467		}
468		return fmt.Sprintf("https://%s/%s/%s.git", hostPort, info.Owner, info.Repo), true
469	}
470	
471	func providerHost(provider string) (string, bool) {
472		switch strings.ToLower(strings.TrimSpace(provider)) {
473		case "github":
474			return "github.com", true
475		case "gitlab":
476			return "gitlab.com", true
477		default:
478			return "", false
479		}
480	}
481	
482	// RedactURL removes credentials and query parameters from a URL for safe logging.
483	func RedactURL(rawURL string) string {
484		return gitremote.RedactURL(rawURL)
485	}
486	
487	func logFallback(ctx context.Context, operation, fallbackURL, reason string, err error, attrs ...any) {
488		logAttrs := []any{
489			slog.String("operation", operation),
490			slog.String("fallback_url", RedactURL(fallbackURL)),
491			slog.String("reason", reason),
492			slog.String("error", err.Error()),
493		}
494		logAttrs = append(logAttrs, attrs...)
495		logging.Warn(ctx, "checkpoint remote URL resolution fell back to alternate remote URL", logAttrs...)
496	}
497	
498	func resolvePushFallbackURL(ctx context.Context, pushRemoteName, originURL string) (string, error) {
499		if originURL != "" {
500			if strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar)) != "" {
501				if tokenURL, ok := deriveTokenOriginURL(originURL); ok {
502					return tokenURL, nil
503				}
504			}
505			return originURL, nil
506		}
507		if pushRemoteName == "" {
508			return "", fmt.Errorf("no push remote specified and remote %q not found", originRemote)
509		}
510		if pushRemoteName == originRemote {
511			return "", fmt.Errorf("remote %q not found", originRemote)
512		}
513		pushURL, err := GetRemoteURL(ctx, pushRemoteName)
514		if err != nil {
515			return "", err
516		}
517		if strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar)) != "" {
518			if tokenURL, ok := deriveTokenOriginURL(pushURL); ok {
519				return tokenURL, nil
520			}
521		}
522		return pushURL, nil
523	}
